import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalLength = scanner.nextInt();
        String sequence = scanner.next();
        boolean insideParentheses = false;
        StringBuilder currentSegment = new StringBuilder();
        int maxSegmentLength = 0;
        int insideWordsTotal = 0;
        for (int i = 0; i < totalLength; i++) {
            char ch = sequence.charAt(i);
            if (ch == '(') {
                if (!insideParentheses) {
                    String[] outsideParts = currentSegment.toString().split("_");
                    for (String part : outsideParts) {
                        maxSegmentLength = Math.max(maxSegmentLength, part.length());
                    }
                }
                insideParentheses = true;
                currentSegment = new StringBuilder();
            } else if (ch == ')') {
                insideParentheses = false;
                String[] insideParts = currentSegment.toString().split("_");
                for (String part : insideParts) {
                    if (!part.isEmpty()) {
                        insideWordsTotal++;
                    }
                }
                currentSegment = new StringBuilder();
            } else {
                currentSegment.append(ch);
            }
        }
        String[] outsideRemaining = currentSegment.toString().split("_");
        for (String part : outsideRemaining) {
            maxSegmentLength = Math.max(maxSegmentLength, part.length());
        }
        System.out.println(maxSegmentLength + " " + insideWordsTotal);
    }
}
